const inR=d=>!d?(!r1&&!r2):(!r1||d>=r1)&&(!r2||d<=r2);
function relger(h){const R=REP.find(x=>x[0]===rk),o=R[3](),fmt=(v,i)=>(o.money||[]).includes(i)?money(v):v;
 const tot=o.sums?o.sums.map(i=>o.rows.reduce((a,r)=>a+Number(r[i]||0),0)):null;
 h.innerHTML=`<div class="sy-h"><div><small>Administração</small><h1>Relatórios</h1></div><div class="ad-tools"><button class="al-btn sec" id="rx">${ic('table')}Exportar CSV</button><button class="al-btn sec" id="rp">${ic('printer')}Imprimir</button></div></div>
 <div class="sy-tabs">${REP.map(r=>`<button data-k="${r[0]}" class="${rk===r[0]?'on':''}">${ic(r[2])}${r[1]}</button>`).join('')}</div>
 <div class="ad-bar"><label class="rp-f">De <input type="date" id="rd1" value="${r1}"></label><label class="rp-f">Até <input type="date" id="rd2" value="${r2}"></label><select id="ruf" class="sy-sel" aria-label="Estado"><option value="">Todos os estados</option>${ufOpts().map(u=>`<option ${rUF===u?'selected':''}>${u}</option>`).join('')}</select><button class="al-btn sec" id="rcl">Limpar filtros</button></div>
 <div class="al-panel"><h3 class="sy-sec">${R[1]} <span class="sy-sub">· ${o.rows.length} registro(s)</span></h3><div class="rp-wrap"><table class="rp-tbl"><thead><tr>${o.head.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${o.rows.map(r=>`<tr>${r.map((v,i)=>`<td>${esc(fmt(v,i))}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="${o.head.length}" class="text-secondary">Nenhum dado para esse filtro.</td></tr>`}</tbody>${tot?`<tfoot><tr><td>Total</td>${o.head.slice(1).map((_,k)=>{const i=k+1,j=o.sums.indexOf(i);return`<td>${j>=0?esc(fmt(tot[j],i)):''}</td>`}).join('')}</tr></tfoot>`:''}</table></div></div>`;
 h.querySelector('.sy-tabs').onclick=e=>{const b=e.target.closest('button');if(b){rk=b.dataset.k;relger(h)}};
 $('#rd1',h).onchange=e=>{r1=e.target.value;relger(h)};$('#rd2',h).onchange=e=>{r2=e.target.value;relger(h)};$('#ruf',h).onchange=e=>{rUF=e.target.value;relger(h)};$('#rcl',h).onclick=()=>{r1=r2=rUF='';relger(h)};
 $('#rp',h).onclick=()=>window.print();$('#rx',h).onclick=()=>csv('relatorio-'+rk+'.csv',o.head,o.rows.map(r=>r.map((v,i)=>(o.money||[]).includes(i)?String(v).replace('.',','):v)))}
